files.content:
/**
 * GameScience house theme — clear, restrained, enterprise-ready.
 */

[data-theme="gamescience"] {
  --background: 210 40% 98%;
  --foreground: 222 47% 11%;

  --surface: 0 0% 100%;
  --surface-subtle: 214 32% 96%;
  --surface-raised: 0 0% 100%;
  --surface-overlay: 0 0% 100%;

  --border: 214 28% 88%;
  --border-strong: 215 19% 55%;
  --focus-ring: 221 83% 53%;

  --primary: 221 83% 53%;
  --primary-hover: 224 76% 48%;
  --primary-active: 226 71% 40%;
  --primary-foreground: 0 0% 100%;

  --secondary: 214 32% 94%;
  --secondary-hover: 214 28% 88%;
  --secondary-active: 213 24% 80%;
  --secondary-foreground: 222 47% 18%;

  --accent: 173 58% 39%;
  --accent-foreground: 0 0% 100%;

  --muted: 210 30% 94%;
  --muted-foreground: 215 16% 42%;

  --success: 152 61% 34%;
  --success-foreground: 0 0% 100%;
  --warning: 38 92% 48%;
  --warning-foreground: 26 83% 14%;
  --danger: 0 72% 48%;
  --danger-foreground: 0 0% 100%;
  --information: 205 90% 42%;
  --information-foreground: 0 0% 100%;

  --radius-control: 0.625rem;
  --radius-card: 0.875rem;
  --radius-panel: 1rem;
  --radius-overlay: 1.125rem;
  --radius-pill: 9999px;

  --border-width-control: 1px;
  --border-width-panel: 1px;

  --font-display: "Source Sans 3", "Segoe UI", sans-serif;
  --font-body: "Source Sans 3", "Segoe UI", sans-serif;
  --font-mono: "IBM Plex Mono", ui-monospace, monospace;

  --font-weight-heading: 700;
  --font-weight-label: 600;
  --font-weight-body: 400;

  --tracking-heading: -0.015em;
  --tracking-label: 0.01em;
  --text-transform-label: none;

  --control-height-sm: 2rem;
  --control-height-md: 2.5rem;
  --control-height-lg: 3rem;

  --control-padding-inline-sm: 0.75rem;
  --control-padding-inline-md: 1rem;
  --control-padding-inline-lg: 1.25rem;

  --panel-padding-sm: 0.75rem;
  --panel-padding-md: 1.25rem;
  --panel-padding-lg: 1.75rem;

  --section-gap: 1.5rem;
  --content-max-width: 42rem;

  --shadow-control: 0 1px 2px rgb(15 23 42 / 0.05);
  --shadow-card: 0 8px 24px rgb(15 23 42 / 0.07);
  --shadow-overlay: 0 20px 48px rgb(15 23 42 / 0.14);
  --shadow-focus: 0 0 0 3px hsl(var(--focus-ring) / 0.3);

  --duration-fast: 120ms;
  --duration-standard: 200ms;
  --duration-emphasis: 320ms;

  --ease-standard: cubic-bezier(0.2, 0.8, 0.2, 1);
  --ease-emphasis: cubic-bezier(0.16, 1, 0.3, 1);

  --press-scale: 0.985;
  --hover-translate: -1px;

  --gs-shell-gradient: linear-gradient(
    160deg,
    hsl(210 40% 98%) 0%,
    hsl(214 45% 95%) 45%,
    hsl(221 40% 93%) 100%
  );
}

[data-theme="gamescience"][data-context="shared-display"] {
  --background: 222 47% 11%;
  --foreground: 210 40% 98%;
  --surface: 222 40% 14%;
  --surface-subtle: 222 35% 18%;
  --surface-raised: 222 38% 16%;
  --surface-overlay: 222 40% 14%;
  --border: 217 25% 28%;
  --border-strong: 214 28% 55%;
  --muted: 222 30% 20%;
  --muted-foreground: 214 20% 75%;
  --gs-shell-gradient:
    radial-gradient(ellipse at 20% 0%, hsl(221 70% 28% / 0.45), transparent 50%),
    linear-gradient(180deg, hsl(222 47% 11%), hsl(222 45% 8%));
}
